#include <iostream>
#include <thread>
#include <mutex>
using namespace std;

int total = 0;
mutex mtx;

void addMany(int times) {
    for (int i = 0; i < times; i++) {
        lock_guard<mutex> guard(mtx);
        total = total + 1;
    }
}

int main() {
    int times = 0;
    cin >> times;

    thread t1(addMany, times);
    thread t2(addMany, times);
    thread t3(addMany, times);
    t1.join();
    t2.join();
    t3.join();

    cout << "一共 " << total << " {unit}" << endl;
    return 0;
}
